{
  "title": "The Mirror Rescue of Ruinfall",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a broken stained glass window.",
      "visual_description": "Mara the Cartographer stands before a shattered stained glass window in a ruined plaza, her ink-stained coat fluttering. The glass shards reflect fragments of a collapsed spire. She traces a route on a damp map with a brass compass in hand.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp warns of cursed towers.",
      "visual_description": "Inside a crumbling chapel, the Oracle Lamp flickers on a stone altar, its single flame-eye glowing orange. It casts long shadows across faded royal banners hanging from the ceiling. The lamp speaks in a low hum.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the castle gates.",
      "visual_description": "Tin Fox scurries on all fours through a narrow alley, its key-wind tail clicking. Ahead, massive iron castle gates are half-crumbled, entwined with thorny vines. Blue glass eyes scan the entrance for traps.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver swims through a cracked mirror.",
      "visual_description": "Glass Diver, in a clear diving helmet and coat reflecting broken city lights, presses a hand against a tall, cracked mirror in an abandoned guardhouse. The mirror surface ripples like water, and he begins to glide through it.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "Mara finds a hidden passage under a fallen banner.",
      "visual_description": "Mara the Cartographer lifts a heavy, moth-eaten royal banner from a heap of rubble, revealing a stone trapdoor. Tin Fox sniffs at the edges, tail whirring. Dust motes dance in a shaft of pale light.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The Oracle Lamp warns of a trap ahead.",
      "visual_description": "In a narrow corridor lined with faded tapestries, the Oracle Lamp hovers, its flame-eye narrowing. It casts a warning glow on a pressure plate in the floor. Glass Diver stands behind it, ready to swim through a nearby pane of glass.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Tin Fox disarms a hidden mechanism.",
      "visual_description": "Tin Fox crouches beside a stone pillar, its metal paw pressing a hidden switch. The grinding sound of gears echoes as a portcullis stops descending. Mara watches from a doorway, map in hand.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "Glass Diver scouts through a window into a guarded courtyard.",
      "visual_description": "Glass Diver peers through a small, round window into a courtyard where armored patrols march in unison. His reflection glimmers on the glass as he notes their route, then pulls back.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The Sleeping Tax Collector is found dozing in a treasury.",
      "visual_description": "In a dusty treasury room, the Sleeping Tax Collector snores with a ledger book as a pillow, stamped papers stuck to his sleeves. Coins are scattered on the floor. Mara nudges him, but he only mumbles.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "Oracle Lamp reveals a magic door's riddle.",
      "visual_description": "The Oracle Lamp floats before a tall, rune-covered magic door. Its flame-eye reads the glowing symbols, then speaks a riddle. Tin Fox tilts its head, gears whirring as it processes the clue.",
      "characters": ["oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver swims through the magic door's keyhole.",
      "visual_description": "Glass Diver shrinks his form and dives into the keyhole of the magic door, swimming through a liquid light. On the other side, he releases a latch from within, and the door groans open.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Mara navigates a crumbling spire using her map.",
      "visual_description": "Mara the Cartographer climbs a winding stair in a leaning spire, her ink-stained coat brushing against broken stones. She consults her map, which glows faintly, and points upward. Tin Fox follows, claws clicking on the steps.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Oracle Lamp warns of a collapse ahead.",
      "visual_description": "At a landing in the spire, the Oracle Lamp flickers rapidly, its flame-eye widening. It projects a vision of a collapsing floor. Glass Diver and Mara halt, looking at the cracked tiles before them.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "Tin Fox leads the group across a narrow beam.",
      "visual_description": "Tin Fox dashes across a narrow stone beam suspended over a dark chasm, its tail balancing. Mara follows carefully, holding her map. The Oracle Lamp floats behind, casting a steady light.",
      "characters": ["tin_fox", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The Sleeping Tax Collector is left behind in a locked room.",
      "visual_description": "In a dusty side chamber, the Sleeping Tax Collector is curled up on a pile of old ledgers, still snoring. Glass Diver closes the iron door behind him, locking it with a key. The group moves on without him.",
      "characters": ["sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "Mara finds the rescue target in a tower cell.",
      "visual_description": "Mara the Cartographer pushes open a cell door in the highest tower. A figure in chains looks up. The Oracle Lamp casts a warm glow, and Tin Fox scurries forward to inspect the lock.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The group flees down the tower as it starts to crumble.",
      "visual_description": "Mara, Glass Diver, Oracle Lamp, and Tin Fox race down the spiral stair as the tower shakes. Chunks of stone fall behind them. Glass Diver uses his coat to shield them from debris.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They escape across the final bridge at dawn.",
      "visual_description": "At sunrise, the group hurries across a long, rope-and-stone bridge spanning a chasm. The city burns behind them. Mara leads, Tin Fox runs ahead, Oracle Lamp glows softly, and Glass Diver looks back once before crossing.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    }
  ]
}

